commands.command:
cat > /tmp/nftables.conf.candidate <<'ANTRIEB_NFT_EOF'
#!/usr/bin/nft -f

# Persistent host firewall baseline for node1.
destroy table inet filter

table inet filter {
  chain input {
    type filter hook input priority filter; policy drop;

    ct state invalid counter drop comment "drop invalid connections"
    ct state { established, related } counter accept comment "allow established and related connections"
    iifname "lo" counter accept comment "allow loopback"
    meta l4proto { icmp, ipv6-icmp } counter accept comment "allow network control traffic"
    udp sport 67 udp dport 68 counter accept comment "allow DHCPv4 replies"
    tcp dport { 22, 8080 } counter accept comment "allow SSH and TCP 8080"
    counter reject with icmpx type admin-prohibited comment "reject all other inbound traffic"
  }

  chain forward {
    type filter hook forward priority filter; policy drop;
  }
}
ANTRIEB_NFT_EOF
chmod 0644 /tmp/nftables.conf.candidate
nft --check --file /tmp/nftables.conf.candidate
printf '%s\n' 'candidate syntax valid'
sed -n '1,200p' /tmp/nftables.conf.candidate

